# frozen_string_literal: true

# Proves that the Ruby verifier accepts exactly what the TypeScript signer
# emits. contract/token.jwt is regenerated by packages/worker and committed, so
# a mismatch in the claim shape or the encoding shows up as a failing test.
require "minitest/autorun"
require "cloudflare_origin_jwt"

class ContractTest < Minitest::Test
  ROOT = File.expand_path("../../..", __dir__)
  PUBLIC_KEY = File.read(File.join(ROOT, "contract/keys/test-public.pem"))
  TOKEN = File.read(File.join(ROOT, "contract/token.jwt")).strip

  def setup
    CloudflareOriginJwt.reset!
    CloudflareOriginJwt.configure do |config|
      config.public_key = PUBLIC_KEY
      config.issuer = "hairbook-gateway"
      config.audience = "salonpage"
    end
    @app = ->(env) { [200, {}, [env["PATH_INFO"].to_s]] }
    @middleware = CloudflareOriginJwt::Middleware.new(@app)
  end

  def env_for(token)
    { "PATH_INFO" => "/salons/H000749472", "HTTP_X_CF_ORIGIN_JWT" => token }
  end

  def test_accepts_the_token_the_worker_emits
    env = env_for(TOKEN)
    status, = @middleware.call(env)

    assert_equal 200, status
    assert_equal 1, CloudflareOriginJwt.flags(env)["page_published"]
    assert_equal 0, CloudflareOriginJwt.flags(env)["noroshi_reserve"]
    assert_equal "H000749472", CloudflareOriginJwt.claims(env)["sub"]
  end

  def test_rejects_a_token_with_a_changed_payload
    header, _payload, signature = TOKEN.split(".")
    forged = "#{header}.#{Base64.urlsafe_encode64('{"iss":"x"}', padding: false)}.#{signature}"

    assert_equal 404, @middleware.call(env_for(forged)).first
  end

  def test_rejects_the_fixture_when_the_audience_differs
    CloudflareOriginJwt.configure { |config| config.audience = "magazine" }

    assert_equal 404, @middleware.call(env_for(TOKEN)).first
  end
end
